Code.Terraform:
```hcl
# Network policy that only allows access from a VPC endpoint
resource "aws_opensearchserverless_security_policy" "<example_resource_name>" {
  name = "<example_resource_name>"
  type = "network"
  policy = jsonencode([{
    Rules = [
      { ResourceType = "collection", Resource = ["collection/<COLLECTION_NAME>"] },
      { ResourceType = "dashboard", Resource = ["collection/<COLLECTION_NAME>"] }
    ]
    AllowFromPublic = false  # critical: removes internet access
    SourceVPCEs     = ["<VPC_ENDPOINT_ID>"]
  }])
}
```
